"use client";

import { useState } from "react";
import type { AdminFeedbackPostDto, BoardDto, PostId } from "afferent";
import {
  useAdminCapability,
  useAdminFeedback,
  useAdminPost,
  usePostActivity,
  type PostActivityState,
} from "afferent/react.js";

import { AfferentChangelogEditor } from "@/components/afferent/admin/changelog-editor";
import { AfferentFeedbackQueue } from "@/components/afferent/admin/feedback-queue";
import { AfferentMergeDialog } from "@/components/afferent/admin/merge-dialog";
import { AfferentModerationForm } from "@/components/afferent/admin/moderation-form";
import { AfferentTagManager } from "@/components/afferent/admin/tag-manager";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  formatActivityDescription,
  formatAfferentDateTime,
  formatAfferentDateTimeValue,
} from "@/components/afferent/core/format";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export type AfferentAdminMobileView = "queue" | "detail";

export function AfferentAdminScreen({
  boards = [],
  pageOwner = true,
  mobileView,
  onMobileViewChange,
}: Readonly<{
  boards?: readonly BoardDto[];
  pageOwner?: boolean;
  mobileView: AfferentAdminMobileView;
  onMobileViewChange: (view: AfferentAdminMobileView) => void;
}>) {
  const { copy } = useAfferentUi();
  const capability = useAdminCapability();
  const visible = useAdminFeedback("visible");
  const hidden = useAdminFeedback("hidden");
  const [selected, setSelected] = useState<PostId | undefined>();
  const candidates = uniquePosts([...visible.items, ...hidden.items]);

  function select(postId: PostId) {
    setSelected(postId);
    onMobileViewChange("detail");
  }

  function render() {
    switch (capability.status) {
      case "unsupported": {
        return (
          <AfferentStateRegion title={copy.common.unsupportedHeading}>
            <p>{copy.common.unsupportedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "loading": {
        return <AfferentStateRegion title={copy.admin.loading} />;
      }
      case "not-authorized": {
        return (
          <AfferentStateRegion title={copy.common.notAuthorizedHeading}>
            <p>{copy.common.notAuthorizedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "error": {
        return (
          <AfferentStateRegion title={copy.admin.loadError} tone="error">
            <p>{afferentErrorText(capability.error)}</p>
            <p>{copy.common.queryErrorGuidance}</p>
          </AfferentStateRegion>
        );
      }
      case "ready": {
        return (
          <div
            className="afferent-admin-workspace"
            data-admin-workspace
            data-mobile-view={mobileView}
          >
            <div className="afferent-admin-pane" data-admin-pane="queue">
              <AfferentFeedbackQueue
                feed={visible}
                selectedId={selected}
                onSelect={select}
              />
            </div>
            <div className="afferent-admin-pane" data-admin-pane="detail">
              <button
                type="button"
                className="afferent-admin__return"
                onClick={() => onMobileViewChange("queue")}
              >
                {copy.admin.returnToQueue}
              </button>
              <AdminDetail
                postId={selected}
                boards={boards}
                candidates={candidates}
                onReturnToQueue={() => onMobileViewChange("queue")}
              />
              <section className="afferent-admin-section" data-admin-section="changelog">
                <AfferentChangelogEditor feedback={candidates} />
              </section>
            </div>
          </div>
        );
      }
      default: {
        return assertNever(capability);
      }
    }
  }

  const body = (
    <div className="afferent-admin" data-afferent-screen="admin">
      <header>
        <h1>{copy.admin.title}</h1>
      </header>
      {render()}
    </div>
  );
  return pageOwner ? <main>{body}</main> : body;
}

function uniquePosts(items: readonly AdminFeedbackPostDto[]) {
  return [...new Map(items.map((item) => [item.feedback.id, item])).values()];
}

function AdminDetail({
  postId,
  boards,
  candidates,
  onReturnToQueue,
}: Readonly<{
  postId?: PostId;
  boards: readonly BoardDto[];
  candidates: readonly AdminFeedbackPostDto[];
  onReturnToQueue: () => void;
}>) {
  const { copy } = useAfferentUi();
  if (!postId)
    return (
      <AfferentStateRegion title={copy.admin.selectFeedbackHeading}>
        <p>{copy.admin.selectFeedbackBody}</p>
      </AfferentStateRegion>
    );
  return (
    <AdminPostDetail
      postId={postId}
      boards={boards}
      candidates={candidates}
      onReturnToQueue={onReturnToQueue}
    />
  );
}

function AdminPostDetail({
  postId,
  boards,
  candidates,
  onReturnToQueue,
}: Readonly<{
  postId: PostId;
  boards: readonly BoardDto[];
  candidates: readonly AdminFeedbackPostDto[];
  onReturnToQueue: () => void;
}>) {
  const { copy } = useAfferentUi();
  const state = useAdminPost(postId);
  const activity = usePostActivity(postId);
  switch (state.status) {
    case "unsupported": {
      return (
        <AfferentStateRegion title={copy.admin.detailUnsupportedHeading}>
          <p>{copy.common.unsupportedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "loading": {
      return <AfferentStateRegion title={copy.admin.loadingDetail} />;
    }
    case "not-authorized": {
      return (
        <AfferentStateRegion title={copy.common.notAuthorizedHeading}>
          <p>{copy.common.notAuthorizedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion
          title={copy.admin.detailErrorHeading}
          tone="error"
          action={
            <button type="button" onClick={onReturnToQueue}>
              {copy.admin.returnToQueue}
            </button>
          }
        >
          <p>{afferentErrorText(state.error)}</p>
        </AfferentStateRegion>
      );
    }
    case "ready": {
      return (
        <section className="afferent-admin-detail">
          <section className="afferent-admin-section" data-admin-section="moderation">
            <AfferentModerationForm post={state.post} boards={boards} />
          </section>
          <section className="afferent-admin-section" data-admin-section="tags">
            <AfferentTagManager post={state.post} />
          </section>
          <section className="afferent-admin-section" data-admin-section="activity">
            <AdminActivity activity={activity} />
          </section>
          <section className="afferent-admin-section" data-admin-section="merge">
            <AfferentMergeDialog source={state.post} candidates={candidates} />
          </section>
        </section>
      );
    }
    default: {
      return assertNever(state);
    }
  }
}

function AdminActivity({
  activity,
}: Readonly<{ activity: PostActivityState }>) {
  const { copy } = useAfferentUi();
  switch (activity.status) {
    case "unsupported": {
      return (
        <AfferentStateRegion title={copy.admin.activityUnsupportedHeading}>
          <p>{copy.common.unsupportedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "loading": {
      return <AfferentStateRegion title={copy.admin.activityLoading} />;
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.admin.activityEmptyHeading}>
          <p>{copy.admin.activityEmptyBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion
          title={copy.admin.activityErrorHeading}
          tone="error"
          action={
            <button type="button" onClick={activity.retry}>
              {copy.common.tryLoadingAgain}
            </button>
          }
        >
          {activity.error ? <p>{afferentErrorText(activity.error)}</p> : null}
        </AfferentStateRegion>
      );
    }
    case "ready": {
      return (
        <section className="afferent-admin-activity">
          <h2>{copy.admin.activityHeading}</h2>
          <ol>
            {activity.items.map((item) => (
              <li key={item.id}>
                <p>{formatActivityDescription(item)}</p>
                <time dateTime={formatAfferentDateTimeValue(item.occurredAt)}>
                  {formatAfferentDateTime(item.occurredAt)}
                </time>
              </li>
            ))}
          </ol>
          {activity.canLoadMore ? (
            <button
              type="button"
              disabled={activity.isLoadingMore}
              aria-busy={activity.isLoadingMore}
              onClick={activity.loadMore}
            >
              {activity.isLoadingMore
                ? copy.admin.loadingMoreActivity
                : copy.admin.loadMoreActivity}
            </button>
          ) : null}
        </section>
      );
    }
    default: {
      return assertNever(activity);
    }
  }
}

"use client";

import { useState, type FormEvent } from "react";
import type { AdminChangelogEntryDto, AdminFeedbackPostDto } from "afferent";
import {
  changelogActionKey,
  useAdminChangelog,
  useChangelogEditor,
} from "afferent/react.js";

import { AfferentConfirmationDialog } from "@/components/afferent/admin/confirmation-dialog";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  formatAfferentDateTime,
  formatAfferentDateTimeValue,
  formatEditorialState,
} from "@/components/afferent/core/format";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentChangelogEditor({
  feedback,
}: Readonly<{ feedback: readonly AdminFeedbackPostDto[] }>) {
  const { copy } = useAfferentUi();
  const entries = useAdminChangelog();
  const editor = useChangelogEditor();
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");
  const createKey = changelogActionKey("new", "create");

  async function create(event: FormEvent) {
    event.preventDefault();
    const result = await editor.createDraft({ title, body });
    if (result.ok) {
      setTitle("");
      setBody("");
    }
  }

  function renderEditorState() {
    switch (editor.status) {
      case "unsupported": {
        return (
          <AfferentStateRegion title={copy.admin.changelogUnsupportedHeading}>
            <p>{copy.common.unsupportedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "loading": {
        return <AfferentStateRegion title={copy.admin.changelogLoading} />;
      }
      case "not-authorized": {
        return (
          <AfferentStateRegion title={copy.admin.changelogNotAuthorizedHeading}>
            <p>{copy.common.notAuthorizedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "ready": {
        return (
          <form onSubmit={(event) => void create(event)}>
            <label>
              {copy.admin.changelogTitleLabel}
              <input
                value={title}
                onChange={(event) => setTitle(event.currentTarget.value)}
              />
            </label>
            <label>
              {copy.admin.changelogBodyLabel}
              <textarea
                value={body}
                onChange={(event) => setBody(event.currentTarget.value)}
              />
            </label>
            <button
              type="submit"
              disabled={editor.pending[createKey]}
              aria-busy={editor.pending[createKey]}
            >
              {copy.admin.saveChangelogDraft}
            </button>
            {editor.errors[createKey] ? (
              <div className="afferent-inline-error" role="alert">
                <p>{afferentErrorText(editor.errors[createKey]!)}</p>
                <button
                  type="button"
                  onClick={() => editor.reset("new", "create")}
                >
                  {copy.admin.dismissMutationError}
                </button>
              </div>
            ) : null}
          </form>
        );
      }
      default: {
        return assertNever(editor.status as never);
      }
    }
  }

  function renderEntries() {
    switch (entries.status) {
      case "unsupported": {
        return (
          <AfferentStateRegion title={copy.admin.changelogUnsupportedHeading}>
            <p>{copy.common.unsupportedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "loading": {
        return <AfferentStateRegion title={copy.admin.changelogLoading} />;
      }
      case "not-authorized": {
        return (
          <AfferentStateRegion title={copy.admin.changelogNotAuthorizedHeading}>
            <p>{copy.common.notAuthorizedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "empty": {
        return (
          <AfferentStateRegion title={copy.admin.changelogEmptyHeading}>
            <p>{copy.admin.changelogEmptyBody}</p>
          </AfferentStateRegion>
        );
      }
      case "error": {
        return (
          <AfferentStateRegion
            title={copy.admin.changelogErrorHeading}
            tone="error"
            action={
              <button type="button" onClick={entries.loadMore}>
                {copy.common.tryLoadingAgain}
              </button>
            }
          >
            {entries.error ? <p>{afferentErrorText(entries.error)}</p> : null}
          </AfferentStateRegion>
        );
      }
      case "loading-more":
      case "ready": {
        return (
          <>
            <ol>
              {entries.items.map((entry) => (
                <Entry
                  key={entry.id}
                  entry={entry}
                  feedback={feedback}
                  editor={editor}
                />
              ))}
            </ol>
            {entries.canLoadMore ? (
              <button
                type="button"
                disabled={entries.status === "loading-more"}
                aria-busy={entries.status === "loading-more"}
                onClick={entries.loadMore}
              >
                {entries.status === "loading-more"
                  ? copy.admin.loadingMoreChangelog
                  : copy.admin.loadMoreChangelog}
              </button>
            ) : null}
          </>
        );
      }
      default: {
        return assertNever(entries.status as never);
      }
    }
  }

  return (
    <section className="afferent-changelog-editor">
      <h2>{copy.admin.changelogHeading}</h2>
      {renderEditorState()}
      {renderEntries()}
    </section>
  );
}

function Entry({
  entry,
  feedback,
  editor,
}: Readonly<{
  entry: AdminChangelogEntryDto;
  feedback: readonly AdminFeedbackPostDto[];
  editor: ReturnType<typeof useChangelogEditor>;
}>) {
  const { copy } = useAfferentUi();
  const action = entry.state === "published" ? "unpublish" : "publish";
  const key = changelogActionKey(entry.id, action);
  const published = entry.state === "published";
  return (
    <li>
      <article>
        <header>
          <h3>{entry.title}</h3>
          <p>{formatEditorialState(entry.state)}</p>
          <time dateTime={formatAfferentDateTimeValue(entry.updatedAt)}>
            Updated {formatAfferentDateTime(entry.updatedAt)}
          </time>
        </header>
        <fieldset>
          <legend>{copy.admin.linkedFeedback}</legend>
          {feedback.map((post) => (
            <label key={post.feedback.id}>
              <input
                type="checkbox"
                defaultChecked={entry.links.some(
                  (link) => link.id === post.feedback.id,
                )}
                disabled={editor.pending[changelogActionKey(entry.id, "links")]}
                onChange={() =>
                  void editor.setLinks({
                    entryId: entry.id,
                    postIds: [post.feedback.id],
                  })
                }
              />
              {post.feedback.title}
            </label>
          ))}
        </fieldset>
        <div className={published ? "afferent-destructive-actions" : undefined}>
          <AfferentConfirmationDialog
            triggerLabel={
              published
                ? copy.admin.unpublishChangelog
                : copy.admin.publishChangelog
            }
            title={
              published
                ? copy.admin.unpublishTitle(entry.title)
                : copy.admin.publishTitle(entry.title)
            }
            description={
              published ? copy.admin.unpublishBody : copy.admin.publishBody
            }
            confirmLabel={
              published
                ? copy.admin.unpublishChangelog
                : copy.admin.publishChangelog
            }
            escapeLabel={
              published
                ? copy.admin.keepChangelogPublished
                : copy.admin.returnToEditing
            }
            destructive={published}
            pending={editor.pending[key] ?? false}
            error={editor.errors[key]}
            onReset={() => editor.reset(entry.id, action)}
            onConfirm={() =>
              published ? editor.unpublish(entry.id) : editor.publish(entry.id)
            }
          />
        </div>
      </article>
    </li>
  );
}

"use client";

import { useEffect, useRef, useState, type RefObject } from "react";
import { Dialog } from "radix-ui";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import { afferentErrorText } from "@/components/afferent/core/state-region";

type ConfirmationResult = Readonly<{ ok: boolean }> | void;

export function AfferentConfirmationDialog({
  triggerLabel,
  title,
  description,
  confirmLabel,
  escapeLabel,
  pending,
  error,
  onConfirm,
  onReset,
  restoreFocusTo,
  destructive = false,
}: Readonly<{
  triggerLabel: string;
  title: string;
  description: string;
  confirmLabel: string;
  escapeLabel: string;
  pending: boolean;
  error?: Readonly<{ code: string; message?: string }>;
  onConfirm: () => Promise<ConfirmationResult>;
  onReset: () => void;
  restoreFocusTo?: RefObject<HTMLElement | null>;
  destructive?: boolean;
}>) {
  const { copy } = useAfferentUi();
  const [open, setOpen] = useState(false);
  const trigger = useRef<HTMLButtonElement>(null);
  const opened = useRef(false);

  useEffect(() => {
    if (open) {
      opened.current = true;
    } else if (opened.current) {
      opened.current = false;
      restoreFocus();
    }
  }, [open]);

  async function confirm() {
    const result = await onConfirm();
    if (result && result.ok) {
      setOpen(false);
    }
  }

  function restoreFocus() {
    const target = trigger.current?.isConnected
      ? trigger.current
      : restoreFocusTo?.current;
    target?.focus();
  }

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(nextOpen) => {
        if (pending && !nextOpen) return;
        if (!nextOpen && error) onReset();
        setOpen(nextOpen);
      }}
    >
      <Dialog.Trigger asChild>
        <button
          ref={trigger}
          type="button"
          className={destructive ? "afferent-button--destructive" : undefined}
        >
          {triggerLabel}
        </button>
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Overlay className="afferent-dialog-overlay" />
        <Dialog.Content
          className="afferent-dialog"
          data-tone={destructive ? "destructive" : "consequential"}
          onEscapeKeyDown={(event) => {
            if (pending) event.preventDefault();
          }}
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            restoreFocus();
          }}
        >
          <Dialog.Title>{title}</Dialog.Title>
          <Dialog.Description>{description}</Dialog.Description>
          {error ? (
            <div className="afferent-inline-error" role="alert">
              <h3>{copy.admin.mutationErrorHeading(confirmLabel)}</h3>
              <p>{afferentErrorText(error)}</p>
              <button type="button" onClick={onReset}>
                {copy.admin.dismissMutationError}
              </button>
            </div>
          ) : null}
          <div className="afferent-dialog__actions">
            <button
              type="button"
              className={
                destructive ? "afferent-button--destructive" : undefined
              }
              disabled={pending}
              aria-busy={pending}
              onClick={() => void confirm()}
            >
              {confirmLabel}
            </button>
            <Dialog.Close asChild>
              <button type="button" disabled={pending}>
                {escapeLabel}
              </button>
            </Dialog.Close>
          </div>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

import type { PostId } from "afferent";
import type { AdminFeedbackState } from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentFeedbackQueue({
  feed,
  selectedId,
  onSelect,
}: Readonly<{
  feed: AdminFeedbackState;
  selectedId?: string;
  onSelect: (id: PostId) => void;
}>) {
  const { copy } = useAfferentUi();
  switch (feed.status) {
    case "unsupported": {
      return (
        <AfferentStateRegion title={copy.common.unsupportedHeading}>
          <p>{copy.common.unsupportedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "loading": {
      return <AfferentStateRegion title={copy.admin.loading} />;
    }
    case "not-authorized": {
      return (
        <AfferentStateRegion title={copy.common.notAuthorizedHeading}>
          <p>{copy.common.notAuthorizedBody}</p>
        </AfferentStateRegion>
      );
    }
    case "empty": {
      return (
        <AfferentStateRegion title={copy.admin.emptyHeading}>
          <p>{copy.admin.emptyBody}</p>
        </AfferentStateRegion>
      );
    }
    case "error": {
      return (
        <AfferentStateRegion
          title={copy.admin.loadError}
          tone="error"
          action={
            <button type="button" onClick={feed.loadMore}>
              {copy.common.tryLoadingAgain}
            </button>
          }
        >
          {feed.error ? <p>{afferentErrorText(feed.error)}</p> : null}
        </AfferentStateRegion>
      );
    }
    case "loading-more":
    case "ready": {
      return (
        <section aria-label={copy.admin.queueHeading}>
          <h2>{copy.admin.queueHeading}</h2>
          <ol className="afferent-admin-queue">
            {feed.items.map((item) => {
              const selected = selectedId === item.feedback.id;
              return (
                <li
                  key={item.feedback.id}
                  data-admin-feedback
                  data-selected={selected}
                >
                  <button
                    type="button"
                    aria-current={selected ? "true" : undefined}
                    onClick={() => onSelect(item.feedback.id)}
                  >
                    {selected ? (
                      <span className="afferent-admin-queue__selection">
                        {copy.admin.selectedFeedback}
                      </span>
                    ) : null}
                    <span data-admin-label="Feedback">
                      {item.feedback.title}
                    </span>
                    <span data-admin-label="Status">
                      {item.feedback.status.label}
                    </span>
                    <span data-admin-label="Board">
                      {item.feedback.board.name}
                    </span>
                  </button>
                </li>
              );
            })}
          </ol>
          {feed.canLoadMore ? (
            <button
              type="button"
              className="afferent-button afferent-button--secondary"
              onClick={feed.loadMore}
              disabled={feed.status === "loading-more"}
              aria-busy={feed.status === "loading-more"}
            >
              {feed.status === "loading-more"
                ? copy.common.loading
                : copy.admin.loadMore}
            </button>
          ) : null}
        </section>
      );
    }
    default: {
      return assertNever(feed.status as never);
    }
  }
}

"use client";

import { useEffect, useRef, useState } from "react";
import type { AdminFeedbackPostDto, PostId } from "afferent";
import { Dialog } from "radix-ui";
import { moderationActionKey, useMergePost } from "afferent/react.js";

import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import { afferentErrorText } from "@/components/afferent/core/state-region";

export function AfferentMergeDialog({
  source,
  candidates,
}: Readonly<{
  source: AdminFeedbackPostDto;
  candidates: readonly AdminFeedbackPostDto[];
}>) {
  const { copy } = useAfferentUi();
  const merge = useMergePost();
  const available = candidates.filter(
    (item) => item.feedback.id !== source.feedback.id,
  );
  const [open, setOpen] = useState(false);
  const [typed, setTyped] = useState("");
  const [target, setTarget] = useState<PostId | "">(
    available[0]?.feedback.id ?? "",
  );
  const trigger = useRef<HTMLButtonElement>(null);
  const opened = useRef(false);
  const key = moderationActionKey(source.feedback.id, "merge");
  const canonical = available.find((item) => item.feedback.id === target);
  const pending = merge.pending[key] ?? false;
  const error = merge.errors[key];

  useEffect(() => {
    if (open) {
      opened.current = true;
    } else if (opened.current) {
      opened.current = false;
      trigger.current?.focus();
    }
  }, [open]);

  async function confirm() {
    if (!target || typed !== source.feedback.title) return;
    const result = await merge.merge({
      sourcePostId: source.feedback.id,
      canonicalPostId: target,
    });
    if (result.ok) {
      setOpen(false);
    }
  }

  return (
    <div className="afferent-destructive-actions">
      <Dialog.Root
        open={open}
        onOpenChange={(nextOpen) => {
          if (pending && !nextOpen) return;
          if (!nextOpen) {
            setTyped("");
            if (error) merge.reset(source.feedback.id);
          }
          setOpen(nextOpen);
        }}
      >
        <Dialog.Trigger asChild>
          <button
            ref={trigger}
            type="button"
            className="afferent-button--destructive"
            disabled={available.length === 0}
          >
            {copy.admin.mergeDuplicate}
          </button>
        </Dialog.Trigger>
        <Dialog.Portal>
          <Dialog.Overlay className="afferent-dialog-overlay" />
          <Dialog.Content
            className="afferent-dialog"
            data-tone="destructive"
            onEscapeKeyDown={(event) => {
              if (pending) event.preventDefault();
            }}
            onCloseAutoFocus={(event) => {
              event.preventDefault();
              trigger.current?.focus();
            }}
          >
            <Dialog.Title>{copy.admin.mergeDuplicate}</Dialog.Title>
            <Dialog.Description>
              {copy.admin.mergeDescription(
                source.feedback.title,
                canonical?.feedback.title ?? "the selected feedback",
              )}
            </Dialog.Description>
            <label>
              {copy.admin.canonicalFeedback}
              <select
                value={target}
                disabled={pending}
                onChange={(event) =>
                  setTarget(event.currentTarget.value as PostId | "")
                }
              >
                {available.map((item) => (
                  <option key={item.feedback.id} value={item.feedback.id}>
                    {item.feedback.title}
                  </option>
                ))}
              </select>
            </label>
            <label>
              {copy.admin.duplicateTitle}
              <input
                value={typed}
                disabled={pending}
                onChange={(event) => setTyped(event.currentTarget.value)}
              />
            </label>
            {error ? (
              <div className="afferent-inline-error" role="alert">
                <h3>
                  {copy.admin.mutationErrorHeading(copy.admin.mergeDuplicate)}
                </h3>
                <p>{afferentErrorText(error)}</p>
                <button
                  type="button"
                  onClick={() => merge.reset(source.feedback.id)}
                >
                  {copy.admin.dismissMutationError}
                </button>
              </div>
            ) : null}
            <div className="afferent-dialog__actions">
              <button
                type="button"
                className="afferent-button--destructive"
                disabled={typed !== source.feedback.title || !target || pending}
                aria-busy={pending}
                onClick={() => void confirm()}
              >
                {copy.admin.mergeDuplicate}
              </button>
              <Dialog.Close asChild>
                <button type="button" disabled={pending}>
                  {copy.detail.keepFeedback}
                </button>
              </Dialog.Close>
            </div>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    </div>
  );
}

"use client";

import { useState, type FormEvent } from "react";
import type { AdminFeedbackPostDto, BoardDto, PostStatusKey } from "afferent";
import {
  moderationActionKey,
  usePostModeration,
  type ModerationAction,
} from "afferent/react.js";

import { AfferentConfirmationDialog } from "@/components/afferent/admin/confirmation-dialog";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import { afferentErrorText } from "@/components/afferent/core/state-region";

const statuses: readonly PostStatusKey[] = [
  "open",
  "under_review",
  "planned",
  "in_progress",
  "complete",
  "closed",
];

const statusLabels: Readonly<Record<PostStatusKey, string>> = {
  open: "Open",
  under_review: "Under Review",
  planned: "Planned",
  in_progress: "In Progress",
  complete: "Complete",
  closed: "Closed",
};

export function AfferentModerationForm({
  post,
  boards,
}: Readonly<{ post: AdminFeedbackPostDto; boards: readonly BoardDto[] }>) {
  const { copy } = useAfferentUi();
  const moderation = usePostModeration();
  const [title, setTitle] = useState(post.feedback.title);
  const [body, setBody] = useState(post.feedback.body);
  const id = post.feedback.id;
  const key = (action: ModerationAction) => moderationActionKey(id, action);

  function save(event: FormEvent) {
    event.preventDefault();
    void moderation.editPost({ postId: id, title, body });
  }

  function error(action: ModerationAction, label: string) {
    const value = moderation.errors[key(action)];
    return value ? (
      <div className="afferent-inline-error" role="alert">
        <h3>{copy.admin.mutationErrorHeading(label)}</h3>
        <p>{afferentErrorText(value)}</p>
        <button type="button" onClick={() => moderation.reset(id, action)}>
          {copy.admin.dismissMutationError}
        </button>
      </div>
    ) : null;
  }

  return (
    <form
      className="afferent-admin-form"
      onSubmit={save}
      aria-label={copy.admin.moderationHeading}
    >
      <h2>{copy.admin.moderationHeading}</h2>
      <label>
        Feedback title
        <input
          value={title}
          onChange={(event) => setTitle(event.currentTarget.value)}
        />
      </label>
      <label>
        Feedback details
        <textarea
          value={body}
          onChange={(event) => setBody(event.currentTarget.value)}
        />
      </label>
      <button
        className="afferent-button"
        type="submit"
        disabled={moderation.pending[key("edit")]}
        aria-busy={moderation.pending[key("edit")]}
      >
        {copy.admin.saveModeration}
      </button>
      {error("edit", copy.admin.saveModeration)}
      <label>
        Board
        <select
          name="board"
          defaultValue={post.feedback.boardId}
          disabled={moderation.pending[key("move")]}
          onChange={(event) =>
            void moderation.movePost({
              postId: id,
              boardId: event.currentTarget.value as any,
            })
          }
        >
          {boards.map((candidate) => (
            <option key={candidate.id} value={candidate.id}>
              {candidate.name}
            </option>
          ))}
        </select>
      </label>
      {error("move", "Move feedback")}
      <label>
        {copy.admin.updateStatus}
        <select
          name="status"
          defaultValue={post.feedback.status.key}
          disabled={moderation.pending[key("status")]}
          onChange={(event) =>
            void moderation.setPostStatus({
              postId: id,
              status: event.currentTarget.value as PostStatusKey,
            })
          }
        >
          {statuses.map((status) => (
            <option key={status} value={status}>
              {statusLabels[status]}
            </option>
          ))}
        </select>
      </label>
      {error("status", copy.admin.updateStatus)}
      <div className="afferent-actions">
        <button
          type="button"
          disabled={moderation.pending[key("lock")]}
          aria-busy={moderation.pending[key("lock")]}
          onClick={() =>
            void moderation.setDiscussionLock({
              postId: id,
              locked: !post.moderation.discussionLocked,
            })
          }
        >
          {post.moderation.discussionLocked
            ? "Unlock discussion"
            : "Lock discussion"}
        </button>
      </div>
      {error(
        "lock",
        post.moderation.discussionLocked
          ? "Unlock discussion"
          : "Lock discussion",
      )}
      <div className="afferent-destructive-actions">
        {post.moderation.archived ? (
          <button
            type="button"
            disabled={moderation.pending[key("archive")]}
            aria-busy={moderation.pending[key("archive")]}
            onClick={() =>
              void moderation.setArchived({ postId: id, archived: false })
            }
          >
            {copy.admin.restoreFeedback}
          </button>
        ) : (
          <AfferentConfirmationDialog
            triggerLabel={copy.admin.archiveFeedback}
            title={copy.admin.archiveTitle(post.feedback.title)}
            description={copy.admin.archiveBody}
            confirmLabel={copy.admin.archiveFeedback}
            escapeLabel={copy.detail.keepFeedback}
            destructive
            pending={moderation.pending[key("archive")] ?? false}
            error={moderation.errors[key("archive")]}
            onReset={() => moderation.reset(id, "archive")}
            onConfirm={() =>
              moderation.setArchived({ postId: id, archived: true })
            }
          />
        )}
        {post.moderation.archived
          ? error("archive", copy.admin.restoreFeedback)
          : null}
      </div>
    </form>
  );
}

"use client";

import { useRef, useState, type FormEvent } from "react";
import type { AdminFeedbackPostDto } from "afferent";
import { tagActionKey, useTagManagement, useTags } from "afferent/react.js";

import { AfferentConfirmationDialog } from "@/components/afferent/admin/confirmation-dialog";
import { useAfferentUi } from "@/components/afferent/core/afferent-ui-provider";
import {
  AfferentStateRegion,
  afferentErrorText,
  assertNever,
} from "@/components/afferent/core/state-region";

export function AfferentTagManager({
  post,
}: Readonly<{ post: AdminFeedbackPostDto }>) {
  const { copy } = useAfferentUi();
  const tags = useTags();
  const management = useTagManagement();
  const [name, setName] = useState("");
  const heading = useRef<HTMLHeadingElement>(null);
  const createKey = tagActionKey("tag", "create");

  async function create(event: FormEvent) {
    event.preventDefault();
    if (!name.trim()) return;
    const result = await management.createTag({ name: name.trim() });
    if (result.ok) setName("");
  }

  function renderTags() {
    switch (tags.status) {
      case "unsupported": {
        return (
          <AfferentStateRegion title={copy.common.unsupportedHeading}>
            <p>{copy.common.unsupportedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "loading": {
        return <AfferentStateRegion title={copy.admin.tagsLoading} />;
      }
      case "not-authorized": {
        return (
          <AfferentStateRegion title={copy.common.notAuthorizedHeading}>
            <p>{copy.common.notAuthorizedBody}</p>
          </AfferentStateRegion>
        );
      }
      case "empty": {
        return (
          <AfferentStateRegion title={copy.admin.tagsEmptyHeading}>
            <p>{copy.admin.tagsEmptyBody}</p>
          </AfferentStateRegion>
        );
      }
      case "error": {
        return (
          <AfferentStateRegion title={copy.admin.tagsErrorHeading} tone="error">
            {tags.error ? <p>{afferentErrorText(tags.error)}</p> : null}
            <p>{copy.common.queryErrorGuidance}</p>
          </AfferentStateRegion>
        );
      }
      case "ready": {
        return (
          <ul>
            {tags.items.map((tag) => {
              const assigned = post.feedback.tags.some(
                (item) => item.id === tag.id,
              );
              const relationKey = tagActionKey(
                `${post.feedback.id}:${tag.id}`,
                assigned ? "remove" : "assign",
              );
              const deleteKey = tagActionKey(tag.id, "delete");
              return (
                <li key={tag.id} className="afferent-tag-manager__row">
                  <span>{tag.name}</span>
                  <div className="afferent-tag-manager__actions">
                    <button
                      type="button"
                      disabled={management.pending[relationKey]}
                      aria-busy={management.pending[relationKey]}
                      onClick={() =>
                        void management.setPostTag({
                          postId: post.feedback.id,
                          tagId: tag.id,
                          desired: !assigned,
                        })
                      }
                    >
                      {assigned ? copy.admin.removeTag : copy.admin.assignTag}
                    </button>
                    <AfferentConfirmationDialog
                      triggerLabel={copy.admin.deleteTag}
                      title={copy.admin.deleteTagTitle(tag.name)}
                      description={copy.admin.deleteTagBody}
                      confirmLabel={copy.admin.deleteTag}
                      escapeLabel={copy.admin.keepTag}
                      destructive
                      pending={management.pending[deleteKey] ?? false}
                      error={management.errors[deleteKey]}
                      onReset={() => management.reset(tag.id, "delete")}
                      onConfirm={() => management.deleteTag({ tagId: tag.id })}
                      restoreFocusTo={heading}
                    />
                  </div>
                  {management.errors[relationKey] ? (
                    <div className="afferent-inline-error" role="alert">
                      <p>
                        {afferentErrorText(management.errors[relationKey]!)}
                      </p>
                      <button
                        type="button"
                        onClick={() =>
                          management.reset(
                            `${post.feedback.id}:${tag.id}`,
                            assigned ? "remove" : "assign",
                          )
                        }
                      >
                        {copy.admin.dismissMutationError}
                      </button>
                    </div>
                  ) : null}
                </li>
              );
            })}
          </ul>
        );
      }
      default: {
        return assertNever(tags.status as never);
      }
    }
  }

  return (
    <section className="afferent-tag-manager">
      <h2 ref={heading} tabIndex={-1}>
        {copy.admin.manageTags}
      </h2>
      <form onSubmit={(event) => void create(event)}>
        <label>
          {copy.admin.newTagLabel}
          <input
            value={name}
            onChange={(event) => setName(event.currentTarget.value)}
          />
        </label>
        <button
          type="submit"
          disabled={management.pending[createKey]}
          aria-busy={management.pending[createKey]}
        >
          {copy.admin.createTag}
        </button>
      </form>
      {management.errors[createKey] ? (
        <div className="afferent-inline-error" role="alert">
          <p>{afferentErrorText(management.errors[createKey]!)}</p>
          <button
            type="button"
            onClick={() => management.reset("tag", "create")}
          >
            {copy.admin.dismissMutationError}
          </button>
        </div>
      ) : null}
      {renderTags()}
    </section>
  );
}
